<?php

declare(strict_types=1);

namespace App\Modules\Platform\Infrastructure\Notifications;

use Illuminate\Bus\Queueable;
use Illuminate\Contracts\Queue\ShouldQueue;
use Illuminate\Mail\Mailable;
use Illuminate\Mail\Mailables\Content;
use Illuminate\Mail\Mailables\Envelope;
use Illuminate\Queue\SerializesModels;

/**
 * Mailable for the email-verification link. The link is a signed
 * URL generated by the caller (AuthMailer) so the signature
 * includes the user id and a hash of the email; tampering with
 * either makes the link invalid.
 *
 * Queueable so a spike of "click here to verify" emails does not
 * block the HTTP thread. Failed deliveries are retried by the
 * standard Laravel queue machinery; the link remains valid for
 * 60 minutes (see `AuthMailer::sendVerificationLink`).
 */
class VerifyEmailMail extends Mailable implements ShouldQueue
{
    use Queueable, SerializesModels;

    public function __construct(
        public string $verifyUrl,
        public string $userName,
    ) {
    }

    public function envelope(): Envelope
    {
        return new Envelope(subject: __('email.verify_subject'));
    }

    public function content(): Content
    {
        return new Content(
            markdown: 'mail.auth.verify-email',
            with: [
                'verifyUrl' => $this->verifyUrl,
                'userName' => $this->userName,
            ],
        );
    }
}